    public F_Order()
    {
        InitializeComponent();
        if (AppSession.Employee == null) { Loaded += (_,__) => { MessageBox.Show("ログインが必要です。"); Close(); }; return; }
        selectedOfficeId = AppSession.Employee.SoId;
        BuildUi(); LoadMasters(); RefreshProducts(); LoadHistory(); UpdateChips();
    }

    Button B(string text, Brush bg, RoutedEventHandler click) { var b=new Button{Content=text,Padding=new Thickness(14,7,14,7),Margin=new Thickness(4),Background=bg,Foreground=Brushes.White,BorderThickness=new Thickness(0),FontWeight=FontWeights.SemiBold}; b.Click+=click; return b; }
    Border Card(UIElement child, Thickness? margin=null) => new(){Child=child,Background=Brushes.White,CornerRadius=new CornerRadius(12),Padding=new Thickness(16),Margin=margin ?? new Thickness(0),ClipToBounds=true,Effect=new System.Windows.Media.Effects.DropShadowEffect{BlurRadius=10,ShadowDepth=2,Opacity=.12}};
    TextBlock Txt(string s,double size=13) => new(){Text=s,FontSize=size,Foreground=new SolidColorBrush(Color.FromRgb(38,50,56)),Margin=new Thickness(2)};
    void BuildUi()
    {
        var root=new Grid(); root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto}); root.RowDefinitions.Add(new RowDefinition()); root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto}); Root.Children.Add(root);
        var top=new Grid{Height=64,Background=Brushes.White}; top.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto}); top.ColumnDefinitions.Add(new ColumnDefinition()); top.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});
        var title=new StackPanel{Margin=new Thickness(14,0,0,0)}; title.Children.Add(Txt("受注管理",22)); title.Children.Add(new TextBlock{Text="顧客注文の入力・検索・確定",Foreground=Brushes.Gray}); Grid.SetColumn(title,0); Grid.SetColumnSpan(title,2); top.Children.Add(title);
        var me=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center}; me.Children.Add(Txt($"{AppSession.Employee!.EmName} / {AppSession.Role} / {AppSession.Employee.So.SoName}")); me.Children.Add(B("ログアウト",new SolidColorBrush(Color.FromRgb(110,120,130)),(_,__)=>Logout())); Grid.SetColumn(me,2); top.Children.Add(me); Grid.SetRow(top,0); root.Children.Add(top);
        var body=new Grid{Margin=new Thickness(22,16,22,18)}; body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto}); body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto}); body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto}); body.RowDefinitions.Add(new RowDefinition()); Grid.SetRow(body,1); root.Children.Add(body);
        var footer=new Grid{Height=64,Background=new SolidColorBrush(Color.FromRgb(244,246,248)),ClipToBounds=true}; var backButton=B("← 戻る",new SolidColorBrush(Color.FromRgb(30,58,95)),(_,__)=>{if(modalOpen)CloseModal();else Close();}); backButton.Height=40; backButton.HorizontalAlignment=HorizontalAlignment.Left; backButton.VerticalAlignment=VerticalAlignment.Center; backButton.Margin=new Thickness(24,0,0,12); Panel.SetZIndex(backButton,20); footer.Children.Add(backButton); Grid.SetRow(footer,2); root.Children.Add(footer);
        var chips=new StackPanel{Orientation=Orientation.Horizontal}; customerChip.Style=null; chips.Children.Add(Chip(customerChip,"顧客")); chips.Children.Add(Chip(countChip,"点数")); chips.Children.Add(Chip(totalChip,"合計")); var select=B("顧客を選択",new SolidColorBrush(Color.FromRgb(46,125,154)),SelectClient); chips.Children.Add(select); Grid.SetRow(chips,1); body.Children.Add(chips);
        var filter=new StackPanel{ClipToBounds=true}; filter.Children.Add(Txt("商品検索・絞り込み",16)); var line=new WrapPanel(); keyword.Width=260; keyword.ToolTip="商品名 / 型番 / メーカ名"; keyword.Margin=new Thickness(3); keyword.KeyDown+=(s,e)=>{if(e.Key==Key.Enter)RefreshProducts();}; line.Children.Add(keyword); Configure(major,"大分類"); Configure(small,"小分類"); Configure(maker,"メーカ"); line.Children.Add(major);line.Children.Add(small);line.Children.Add(maker); stockOnly.Margin=new Thickness(10,8,4,4);safetyOnly.Margin=new Thickness(4,8,4,4);line.Children.Add(stockOnly);line.Children.Add(safetyOnly);line.Children.Add(B("検索",new SolidColorBrush(Color.FromRgb(30,58,95)),(_,__)=>RefreshProducts()));line.Children.Add(B("クリア",Brushes.Gray,(_,__)=>{keyword.Clear();major.SelectedIndex=small.SelectedIndex=maker.SelectedIndex=0;RefreshProducts();})); filter.Children.Add(line); var exp=new Expander{Header="受注履歴検索（機能 8.3）",IsExpanded=false,ClipToBounds=true,Margin=new Thickness(0,8,0,0)}; var hline=new WrapPanel{ClipToBounds=true}; Configure(client,"顧客");Configure(office,"営業所");Configure(state,"状態"); hline.Children.Add(client);hline.Children.Add(office);hline.Children.Add(state);hline.Children.Add(B("履歴検索",new SolidColorBrush(Color.FromRgb(46,125,154)),(_,__)=>LoadHistory()));var detail=B("詳細",new SolidColorBrush(Color.FromRgb(30,58,95)),(_,__)=>{if(history.SelectedItem is OrderRow r)OpenHistory(r.OrId);else MessageBox.Show("履歴行を選択してください。");});hline.Children.Add(detail); var historyCard=new StackPanel{ClipToBounds=true}; history.AutoGenerateColumns=true;history.IsReadOnly=true;history.Height=double.NaN;history.MinHeight=0;history.MaxHeight=180;history.VerticalAlignment=VerticalAlignment.Top;history.VerticalScrollBarVisibility=ScrollBarVisibility.Auto;history.CanUserAddRows=false;history.HeadersVisibility=DataGridHeadersVisibility.Column;history.Background=Brushes.White;history.ClipToBounds=true;history.Margin=new Thickness(0,8,0,0);history.MouseDoubleClick+=(s,e)=>{if(history.SelectedItem is OrderRow r)OpenHistory(r.OrId);};historyCard.Children.Add(history);hline.Children.Add(historyCard);exp.Content=hline;filter.Children.Add(exp); var historyBorder=Card(filter,new Thickness(0,0,0,14));Panel.SetZIndex(historyBorder,1); Grid.SetRow(historyBorder,1); body.Children.Add(historyBorder);
        Grid.SetRow(historyBorder,2);
        var scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,ClipToBounds=true}; cards.HorizontalAlignment=HorizontalAlignment.Left; cards.MaxWidth=1160; scroll.Content=cards; Panel.SetZIndex(scroll,5); Grid.SetRow(scroll,3); body.Children.Add(scroll);
        // モーダルのマスクとFABを同じ親に置くと、透明な親グリッドが通常画面の操作を遮るため分離する。
        modalHost.Visibility=Visibility.Collapsed; modalHost.IsHitTestVisible=false; modalHost.Background=new SolidColorBrush(Color.FromArgb(150,0,0,0)); modalHost.HorizontalAlignment=HorizontalAlignment.Stretch; modalHost.VerticalAlignment=VerticalAlignment.Stretch; Root.Children.Add(modalHost);
        var fab=B("🛒",new SolidColorBrush(Color.FromRgb(30,58,95)),OpenNew); fab.Width=64;fab.Height=64;fab.FontSize=24;fab.HorizontalAlignment=HorizontalAlignment.Right;fab.VerticalAlignment=VerticalAlignment.Bottom;fab.Margin=new Thickness(0,0,30,30); Panel.SetZIndex(fab,20); Root.Children.Add(fab);
    }
    Border Chip(TextBlock t,string label){var p=new StackPanel{Orientation=Orientation.Horizontal};p.Children.Add(Txt(label+": ",12));p.Children.Add(t);return new Border{Child=p,Background=new SolidColorBrush(Color.FromRgb(232,240,244)),CornerRadius=new CornerRadius(16),Padding=new Thickness(10,5,10,5),Margin=new Thickness(3)};}
    void Configure(ComboBox c,string hint){c.Width=180;c.Margin=new Thickness(3);c.DisplayMemberPath="Name";c.SelectionChanged+=(s,e)=>{if(c==major)LoadSmall();};}
    void LoadMasters(){major.Items.Add(new Named(0,"すべて"));foreach(var x in db.MMajorClassifications.Where(x=>x.McFlag==0))major.Items.Add(new Named(x.McId,x.McName));major.SelectedIndex=0;LoadSmall();maker.Items.Add(new Named(0,"すべて"));foreach(var x in db.MMakers.Where(x=>x.MaFlag==0))maker.Items.Add(new Named(x.MaId,x.MaName));maker.SelectedIndex=0;client.Items.Add(new Named(0,"すべて"));foreach(var x in db.MClients.Where(x=>x.ClFlag==0))client.Items.Add(new Named(x.ClId,x.ClName));office.Items.Add(new Named(0,"すべて"));foreach(var x in db.MSalesOffices.Where(x=>x.SoFlag==0))office.Items.Add(new Named(x.SoId,x.SoName));state.ItemsSource=new[]{new Named(-1,"すべて"),new Named(0,"未確定"),new Named(1,"確定")};state.SelectedIndex=0; if(!AppSession.IsAdmin)office.SelectedIndex=Math.Max(0,office.Items.Cast<Named>().ToList().FindIndex(x=>x.Id==AppSession.Employee!.SoId));}
    void LoadSmall(){small.Items.Clear();small.Items.Add(new Named(0,"すべて"));if(major.SelectedItem is Named n && n.Id>0)foreach(var x in db.MSmallClassifications.Where(x=>x.McId==n.Id&&x.ScFlag==0))small.Items.Add(new Named(x.ScId,x.ScName));else foreach(var x in db.MSmallClassifications.Where(x=>x.ScFlag==0))small.Items.Add(new Named(x.ScId,x.ScName));small.SelectedIndex=0;}
    void RefreshProducts(){cards.Children.Clear();var q=db.MProducts.Include(x=>x.Ma).Include(x=>x.Sc).Include(x=>x.TStocks).Where(x=>x.PrFlag==0).AsEnumerable();var k=keyword.Text.Trim();if(k!="")q=q.Where(x=>x.PrName.Contains(k)||x.PrModelNumber.Contains(k)||x.Ma.MaName.Contains(k));if(major.SelectedItem is Named ma&&ma.Id>0)q=q.Where(x=>x.Sc.McId==ma.Id);if(small.SelectedItem is Named sc&&sc.Id>0)q=q.Where(x=>x.ScId==sc.Id);if(maker.SelectedItem is Named mk&&mk.Id>0)q=q.Where(x=>x.MaId==mk.Id);foreach(var p in q){int st=p.TStocks.FirstOrDefault(x=>x.StFlag==0)?.StQuantity??0;if(stockOnly.IsChecked==true&&st<=0)continue;if(safetyOnly.IsChecked==true&&st>p.PrSafetyStock)continue;cards.Children.Add(ProductCard(p,st));}if(cards.Children.Count==0)cards.Children.Add(Txt("条件に一致する商品がありません",18));}
    Border ProductCard(MProduct p,int st){var qty=new TextBox{Text="1",Width=38,TextAlignment=TextAlignment.Center,Margin=new Thickness(3)};var minus=B("−",Brushes.Gray,(_,__)=>ChangeQty(qty,-1));var plus=B("＋",new SolidColorBrush(Color.FromRgb(46,125,154)),(_,__)=>ChangeQty(qty,1));var add=B("カートに追加",new SolidColorBrush(Color.FromRgb(30,58,95)),(_,__)=>AddCart(p,qty));var panel=new StackPanel{Width=230};panel.Children.Add(Txt(p.PrName,16));panel.Children.Add(Txt($"{p.Ma.MaName} / {p.Sc.ScName}"));panel.Children.Add(Txt($"型番 {p.PrModelNumber}　色 {p.PrColor}"));panel.Children.Add(Txt($"単価 {p.Price:N0}円",15));panel.Children.Add(Txt($"在庫 {st}　安全在庫 {p.PrSafetyStock}"));if(st==0)panel.Children.Add(Txt("在庫なし",12));else if(st<=p.PrSafetyStock)panel.Children.Add(Txt("発注推奨",12));var row=new StackPanel{Orientation=Orientation.Horizontal};row.Children.Add(minus);row.Children.Add(qty);row.Children.Add(plus);panel.Children.Add(row);panel.Children.Add(add);return Card(panel,new Thickness(6));}
    void ChangeQty(TextBox box,int d){if(int.TryParse(box.Text,out var n))box.Text=Math.Max(1,n+d).ToString();}
    void AddCart(MProduct p,TextBox q){if(!int.TryParse(q.Text,out var n)||n<1)n=1;var l=cart.FirstOrDefault(x=>x.PrId==p.PrId);if(l==null)cart.Add(new CartLine{PrId=p.PrId,PrName=p.PrName,Price=p.Price,Quantity=n,Stock=p.TStocks.FirstOrDefault(x=>x.StFlag==0)?.StQuantity??0});else l.Quantity+=n;if(l!=null&&l.Quantity>l.Stock)MessageBox.Show($"在庫を超えています（在庫 {l.Stock}）が、追加は許可されます。","在庫警告");UpdateChips();}
    void UpdateChips(){customerChip.Text=selectedClient?.ClName??"顧客未選択";countChip.Text=cart.Sum(x=>x.Quantity).ToString();totalChip.Text=cart.Sum(x=>x.LineTotal).ToString("N0")+"円";}
    void SelectClient(object? s,RoutedEventArgs e){var w=new Window{Title="顧客選択",Width=420,Height=220,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner};var p=new StackPanel{Margin=new Thickness(18)};var c=new ComboBox{ItemsSource=db.MClients.Where(x=>x.ClFlag==0).ToList(),DisplayMemberPath="ClName"};var charge=new TextBox{Text=selectedClient==null?"":selectedClient.ClName,Margin=new Thickness(0,8,0,8)};p.Children.Add(Txt("顧客"));p.Children.Add(c);p.Children.Add(Txt("顧客担当者名"));p.Children.Add(charge);p.Children.Add(B("決定",new SolidColorBrush(Color.FromRgb(30,58,95)),(_,__)=>{selectedClient=c.SelectedItem as MClient;if(selectedClient!=null)selectedClient.ClName=selectedClient.ClName;w.DialogResult=true;w.Close();UpdateChips();}));w.Content=p;w.ShowDialog();}
    void LoadHistory(){var q=db.TOrders.Include(x=>x.Cl).Include(x=>x.So).Include(x=>x.Em).Where(x=>x.OrFlag!=2||hiddenOnly.IsChecked==true);if(!AppSession.IsAdmin)q=q.Where(x=>x.SoId==AppSession.Employee!.SoId);if(client.SelectedItem is Named c&&c.Id>0)q=q.Where(x=>x.ClId==c.Id);if(office.SelectedItem is Named o&&o.Id>0)q=q.Where(x=>x.SoId==o.Id);if(state.SelectedItem is Named st&&st.Id>=0)q=q.Where(x=>(x.OrStateFlag??0)==st.Id);history.ItemsSource=q.OrderByDescending(x=>x.OrDate).Select(x=>new OrderRow{OrId=x.OrId,OrDate=x.OrDate,営業所名=x.So.SoName,社員名=x.Em.EmName,顧客名=x.Cl.ClName,ClCharge=x.ClCharge,状態=(x.OrStateFlag??0)==1?"確定":"未確定",OrFlag=x.OrFlag}).ToList();}
    void OpenNew(object? s,RoutedEventArgs e){if(selectedClient==null){MessageBox.Show("先に顧客を選んでください");SelectClient(null,e);return;}if(cart.Count==0){MessageBox.Show("商品を追加するか、履歴から受注を選んでください");return;}OpenModal(null);}
    void OpenHistory(int id){OpenModal(db.TOrders.Include(x=>x.TOrderDetails).ThenInclude(x=>x.Pr).First(x=>x.OrId==id));}
    void OpenModal(TOrder? order){modalOpen=true;modalHost.IsHitTestVisible=true;modalHost.Visibility=Visibility.Visible;var panel=new Border{Width=720,MaxHeight=Height*.8,Background=Brushes.White,CornerRadius=new CornerRadius(16),Padding=new Thickness(20),HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};var p=new StackPanel();p.Children.Add(Txt(order==null?"受注内容の確認":"受注詳細",22));p.Children.Add(Txt($"顧客: {(order?.Cl?.ClName??selectedClient?.ClName??"未選択")}　営業所: {(order?.So?.SoName??AppSession.Employee!.So.SoName)}"));var list=order==null?cart.Select(x=>new CartLine{PrId=x.PrId,PrName=x.PrName,Price=x.Price,Quantity=x.Quantity,Stock=x.Stock}).ToList():order.TOrderDetails.Select(x=>new CartLine{PrId=x.PrId,PrName=x.Pr.PrName,Price=x.OrTotalPrice/Math.Max(1,x.OrQuantity),Quantity=x.OrQuantity,Stock=db.TStocks.Where(s=>s.PrId==x.PrId&&s.StFlag==0).Select(s=>s.StQuantity).FirstOrDefault()}).ToList();foreach(var l in list){var t=Txt($"{l.PrName}　{l.Price:N0}円 × {l.Quantity} = {l.LineTotal:N0}円",14);if(l.Quantity>l.Stock)t.Background=new SolidColorBrush(Color.FromRgb(255,243,205));p.Children.Add(t);}p.Children.Add(Txt($"合計 {list.Sum(x=>x.LineTotal):N0}円",18));var buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};buttons.Children.Add(B("閉じる",Brushes.Gray,(_,__)=>CloseModal()));if(order==null)buttons.Children.Add(B("受注登録",new SolidColorBrush(Color.FromRgb(30,58,95)),(_,__)=>SaveNew()));else if((order.OrStateFlag??0)==0){buttons.Children.Add(B("受注確定",Brushes.ForestGreen,(_,__)=>Confirm(order.OrId)));if(AppSession.IsAdmin)buttons.Children.Add(B("非表示",Brushes.IndianRed,(_,__)=>Hide(order)));}p.Children.Add(buttons);panel.Child=p;modalHost.Children.Clear();modalHost.Children.Add(panel);}
    void CloseModal(){modalHost.Visibility=Visibility.Collapsed;modalHost.IsHitTestVisible=false;modalOpen=false;}
    void SaveNew(){if(selectedClient==null||cart.Count==0)return;using var d=new SalesManagementContext();var o=new TOrder{SoId=selectedOfficeId,EmId=AppSession.Employee!.EmId,ClId=selectedClient.ClId,ClCharge=null,OrDate=DateTime.Today,OrStateFlag=0,OrFlag=0};d.TOrders.Add(o);d.SaveChanges();foreach(var l in cart)d.TOrderDetails.Add(new TOrderDetail{OrId=o.OrId,PrId=l.PrId,OrQuantity=l.Quantity,OrTotalPrice=l.LineTotal});d.SaveChanges();cart.Clear();CloseModal();UpdateChips();LoadHistory();MessageBox.Show($"受注を登録しました（受注ID: {o.OrId}）");}
    void Confirm(int id){if(!BusinessService.ConfirmOrder(id,AppSession.Employee!.EmId,out var m))MessageBox.Show(m,"エラー");else{MessageBox.Show("受注を確定し、注文管理へ送信しました");CloseModal();LoadHistory();}}
    void Hide(TOrder o){var reason=Microsoft.VisualBasic.Interaction.InputBox("非表示理由を入力してください。","受注の非表示","");if(string.IsNullOrWhiteSpace(reason))return;using var d=new SalesManagementContext();var x=d.TOrders.Find(o.OrId);if(x!=null){x.OrFlag=2;x.OrHidden=reason;d.SaveChanges();}CloseModal();LoadHistory();}
    void Logout(){if(MessageBox.Show("ログアウトしますか？","確認",MessageBoxButton.YesNo)==MessageBoxResult.Yes){AppSession.Employee=null;new F_login().Show();Close();}}
    void Window_KeyDown(object sender,KeyEventArgs e){if(e.Key==Key.Escape&&modalOpen)CloseModal();}
    sealed record Named(int Id,string Name); sealed class CartLine{public int PrId;public string PrName="";public decimal Price;public int Quantity;public int Stock;public decimal LineTotal=>Price*Quantity;} sealed class ProductRow{}
    sealed class OrderRow{public int OrId{get;set;}public DateTime OrDate{get;set;}public string 営業所名{get;set;}="";public string 社員名{get;set;}="";public string 顧客名{get;set;}="";public string? ClCharge{get;set;}public string 状態{get;set;}="";public int OrFlag{get;set;}}
}
